import { timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: UUID generated by Postgres (`gen_random_uuid()`). */
export const pk = () => uuid("id").primaryKey().defaultRandom();

/** Timestamp with time zone. Always stored as UTC instants. */
export const tstz = (name: string) => timestamp(name, { withTimezone: true });

export const createdAt = () => tstz("created_at").notNull().defaultNow();

/** `$onUpdate` fills this in on every Drizzle `update()`. */
export const updatedAt = () =>
  tstz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
